function smParse(text){
  var lines=String(text||'').split(/\r?\n/), urls=[], errors=[];
  for(var i=0;i<lines.length;i++){
    var l=lines[i].trim(); if(!l) continue;
    if(/^https?:\/\/.+/i.test(l)) urls.push(l); else errors.push(l);
  }
  return { urls:urls, errors:errors };
}
function smEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function smBuild(urls, opts){
  opts=opts||{};
  var xml='<?xml version="1.0" encoding="UTF-8"?>\n';
  xml+='<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
  for(var i=0;i<urls.length;i++){
    xml+='  <url><loc>'+smEsc(urls[i])+'</loc>';
    if(opts.lastmod) xml+='<lastmod>'+smEsc(opts.lastmod)+'</lastmod>';
    if(opts.changefreq) xml+='<changefreq>'+smEsc(opts.changefreq)+'</changefreq>';
    if(opts.priority!=null) xml+='<priority>'+opts.priority+'</priority>';
    xml+='</url>\n';
  }
  xml+='</urlset>';
  return xml;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { smParse:smParse, smBuild:smBuild, smEsc:smEsc };
}
if (typeof window !== 'undefined') {
  window.SitemapForgePure = { smParse:smParse, smBuild:smBuild, smEsc:smEsc };
}
